    51  #include <assimp/types.h>
    52  #include <assimp/IOStream.hpp>
    53  #include <assimp/ParsingUtils.h>
    54
    55  #include <vector>
    56
    57  namespace Assimp {
    58
    59  // ---------------------------------------------------------------------------
    60  /**
    61   *  Implementation of a cached stream buffer.
    62   */
    63  template<class T>
    64  class IOStreamBuffer {
    65  public:
    66      /// @brief  The class constructor.
    67      IOStreamBuffer( size_t cache = 4096 * 4096 );
    68
    69      /// @brief  The class destructor.
    70      ~IOStreamBuffer();
    71
    72      /// @brief  Will open the cached access for a given stream.
    73      /// @param  stream      The stream to cache.
    74      /// @return true if successful.
    75      bool open( IOStream *stream );
    76
    77      /// @brief  Will close the cached access.
    78      /// @return true if successful.
    79      bool close();
    80
    81      /// @brief  Returns the file-size.
    82      /// @return The file-size.
    83      size_t size() const;
    84
    85      /// @brief  Returns the cache size.
    86      /// @return The cache size.
    87      size_t cacheSize() const;
    88
    89      /// @brief  Will read the next block.
    90      /// @return true if successful.
    91      bool readNextBlock();
    92
    93      /// @brief  Returns the number of blocks to read.
    94      /// @return The number of blocks.
    95      size_t getNumBlocks() const;
    96
    97      /// @brief  Returns the current block index.
    98      /// @return The current block index.
    99      size_t getCurrentBlockIndex() const;
   100
   101      /// @brief  Returns the current file pos.
   102      /// @return The current file pos.
   103      size_t getFilePos() const;
   104
   105      /// @brief  Will read the next line.
   106      /// @param  buffer      The buffer for the next line.
   107      /// @return true if successful.
   108      bool getNextDataLine( std::vector<T> &buffer, T continuationToken );
   109
   110      /// @brief  Will read the next line ascii or binary end line char.
   111      /// @param  buffer      The buffer for the next line.
   112      /// @return true if successful.
   113      bool getNextLine(std::vector<T> &buffer);
   114
   115      /// @brief  Will read the next block.
   116      /// @param  buffer      The buffer for the next block.
   117      /// @return true if successful.
   118      bool getNextBlock( std::vector<T> &buffer );
   119
   120  private:
   121      IOStream *m_stream;
   122      size_t m_filesize;
   123      size_t m_cacheSize;
   124      size_t m_numBlocks;
   125      size_t m_blockIdx;
   126      std::vector<T> m_cache;
   127      size_t m_cachePos;
   128      size_t m_filePos;
   129  };
   130
   131  template<class T>
   132  AI_FORCE_INLINE
   133  IOStreamBuffer<T>::IOStreamBuffer( size_t cache )
   134  : m_stream( nullptr )
   135  , m_filesize( 0 )
   136  , m_cacheSize( cache )
   137  , m_numBlocks( 0 )
   138  , m_blockIdx( 0 )
   139  , m_cachePos( 0 )
   140  , m_filePos( 0 ) {
   141      m_cache.resize( cache );
   142      std::fill( m_cache.begin(), m_cache.end(), '\n' );
   143  }
   144
   145  template<class T>
   146  AI_FORCE_INLINE
   147  IOStreamBuffer<T>::~IOStreamBuffer() {
   148      // empty
   149  }
   150
   151  template<class T>
   152  AI_FORCE_INLINE
   153  bool IOStreamBuffer<T>::open( IOStream *stream ) {
   154      //  file still opened!
   155      if ( nullptr != m_stream ) {
   156          return false;
   157      }
   158
   159      //  Invalid stream pointer
   160      if ( nullptr == stream ) {
   161          return false;
   162      }
   163
   164      m_stream = stream;
   165      m_filesize = m_stream->FileSize();
   166      if ( m_filesize == 0 ) {
   167          return false;
   168      }
   169      if ( m_filesize < m_cacheSize ) {
   170          m_cacheSize = m_filesize;
   171      }
   172
   173      m_numBlocks = m_filesize / m_cacheSize;
   174      if ( ( m_filesize % m_cacheSize ) > 0 ) {
   175          m_numBlocks++;
   176      }
   177
   178      return true;
   179  }
   180
   181  template<class T>
   182  AI_FORCE_INLINE
   183  bool IOStreamBuffer<T>::close() {
   184      if ( nullptr == m_stream ) {
   185          return false;
   186      }
   187
   188      // init counters and state vars
   189      m_stream    = nullptr;
   190      m_filesize  = 0;
   191      m_numBlocks = 0;
   192      m_blockIdx  = 0;
   193      m_cachePos  = 0;
   194      m_filePos   = 0;
   195
   196      return true;
   197  }
   198
   199  template<class T>
   200  AI_FORCE_INLINE
   201  size_t IOStreamBuffer<T>::size() const {
   202      return m_filesize;
   203  }
   204
   205  template<class T>
   206  AI_FORCE_INLINE
   207  size_t IOStreamBuffer<T>::cacheSize() const {
   208      return m_cacheSize;
   209  }
   210
   211  template<class T>
   212  AI_FORCE_INLINE
   213  bool IOStreamBuffer<T>::readNextBlock() {
   214      m_stream->Seek( m_filePos, aiOrigin_SET );
   215      size_t readLen = m_stream->Read( &m_cache[ 0 ], sizeof( T ), m_cacheSize );
   216      if ( readLen == 0 ) {
   217          return false;
   218      }
   219      if ( readLen < m_cacheSize ) {
   220          m_cacheSize = readLen;
   221      }
   222      m_filePos += m_cacheSize;
   223      m_cachePos = 0;
   224      m_blockIdx++;
   225
   226      return true;
   227  }
   228
   229  template<class T>
   230  AI_FORCE_INLINE
   231  size_t IOStreamBuffer<T>::getNumBlocks() const {
   232      return m_numBlocks;
   233  }
   234
   235  template<class T>
   236  AI_FORCE_INLINE
   237  size_t IOStreamBuffer<T>::getCurrentBlockIndex() const {
   238      return m_blockIdx;
   239  }
   240
   241  template<class T>
   242  AI_FORCE_INLINE
   243  size_t IOStreamBuffer<T>::getFilePos() const {
   244      return m_filePos;
   245  }
   246
   247  template<class T>
   248  AI_FORCE_INLINE
   249  bool IOStreamBuffer<T>::getNextDataLine( std::vector<T> &buffer, T continuationToken ) {
   250      buffer.resize( m_cacheSize );
   251      if ( m_cachePos >= m_cacheSize || 0 == m_filePos ) {
   252          if ( !readNextBlock() ) {
   253              return false;
   254          }
   255      }
   256
   257      bool continuationFound( false );
   258      size_t i = 0;
   259      for( ;; ) {
   260          if ( continuationToken == m_cache[ m_cachePos ] ) {
   261              continuationFound = true;
   262              ++m_cachePos;
   263          }
   264          if ( IsLineEnd( m_cache[ m_cachePos ] ) ) {
   265              if ( !continuationFound ) {
   266                  // the end of the data line
   267                  break;
   268              } else {
   269                  // skip line end
   270                  while ( m_cache[m_cachePos] != '\n') {
   271                      ++m_cachePos;
   272                  }
   273                  ++m_cachePos;
   274                  continuationFound = false;
   275              }
   276          }
   277
   278          buffer[ i ] = m_cache[ m_cachePos ];
   279          ++m_cachePos;
   280          ++i;
   281          if (m_cachePos >= size()) {
   282              break;
   283          }
   284          if ( m_cachePos >= m_cacheSize ) {
   285              if ( !readNextBlock() ) {
   286                  return false;
   287              }
   288          }
   289      }
   290
   291      buffer[ i ] = '\n';
   292      ++m_cachePos;
   293
   294      return true;
   295  }
   296
   297  static AI_FORCE_INLINE
   298  bool isEndOfCache( size_t pos, size_t cacheSize ) {
   299      return ( pos == cacheSize );
   300  }
   301
   302  template<class T>
   303  AI_FORCE_INLINE
   304  bool IOStreamBuffer<T>::getNextLine(std::vector<T> &buffer) {
   305      buffer.resize(m_cacheSize);
   306      if ( isEndOfCache( m_cachePos, m_cacheSize ) || 0 == m_filePos) {
   307         if (!readNextBlock()) {
   308            return false;
   309         }
   310        }
   311
   312      if (IsLineEnd(m_cache[m_cachePos])) {
   313          // skip line end
   314          while (m_cache[m_cachePos] != '\n') {
   315              ++m_cachePos;
   316          }
   317          ++m_cachePos;
   318          if ( isEndOfCache( m_cachePos, m_cacheSize ) ) {
   319              if ( !readNextBlock() ) {
   320                  return false;
   321              }
   322          }
   323      }
   324
   325      size_t i( 0 );
   326      while (!IsLineEnd(m_cache[ m_cachePos ])) {
   327          buffer[i] = m_cache[ m_cachePos ];
   328          ++m_cachePos;
   329          ++i;
   330          if (m_cachePos >= m_cacheSize) {
   331              if (!readNextBlock()) {
   332                  return false;
   333              }
   334          }
   335      }
   336      buffer[i] = '\n';
   337      ++m_cachePos;
   338
   339      return true;
   340  }
   341
   342  template<class T>
   343  AI_FORCE_INLINE
   344  bool IOStreamBuffer<T>::getNextBlock( std::vector<T> &buffer) {
   345      // Return the last block-value if getNextLine was used before
   346      if ( 0 != m_cachePos ) {
   347          buffer = std::vector<T>( m_cache.begin() + m_cachePos, m_cache.end() );
   348          m_cachePos = 0;
   349      } else {
   350          if ( !readNextBlock() ) {
   351              return false;
   352          }
   353
   354          buffer = std::vector<T>(m_cache.begin(), m_cache.end());
   355      }
   356
   357      return true;
   358  }
